var accessToken = nodeState.get("pingAccessToken");
var userId = nodeState.get("pingOneUserId");
var envId = systemEnv.getProperty("esv.envid");
var pairingCode = nodeState.get("pairingKeyCode");
var pairingKeyId = nodeState.get("pairingKeyId");


var requestOptions = {
  method: "GET",
  headers: {
    "Content-Type": "application/json"
  },
  token: accessToken
};



var pairingKey = nodeState.get("pairingKeyUri"); // <-- use your actual sharedState key

function createScript(valueToEncode) {
  return `
(function () {
  const valueToEncode = ${JSON.stringify(String(valueToEncode))};

  function loadScript(src, callback) {
    const s = document.createElement("script");
    s.src = src;
    s.async = true;
    s.onload = callback;
    document.head.appendChild(s);
  }

  loadScript("https://cdn.jsdelivr.net/npm/qrcodejs/qrcode.min.js", function () {
    console.log("QRCode lib loaded");

    const container = document.getElementById("wrapper");

    if (!container) {
      console.error("callbacksPanel not found");
      return;
    }

    const qrDiv = document.createElement("div");
    qrDiv.id = "pairing-qr-code";
    qrDiv.style.textAlign = "center";
    qrDiv.style.width = "100%";
    qrDiv.style.display = "flex";
    qrDiv.style.justifyContent = "center";
    qrDiv.style.alignItems = "center";
    qrDiv.style.margin = "16px 0";

    container.prepend(qrDiv);

    new QRCode(qrDiv, {
      text: valueToEncode
    });
  });
})();
`;
}


var url = `https://api.pingone.com/v1/environments/${envId}/users/${userId}/pairingKeys/${pairingKeyId}`;

if (callbacks.isEmpty()) {
    logger.info("Displaying pairing code to user: " + pairingCode);
    callbacksBuilder.scriptTextOutputCallback(createScript(pairingKey));
    callbacksBuilder.textOutputCallback(0, "Pairing Code: " + pairingCode);
    callbacksBuilder.confirmationCallback(0, ["Paired"], 0);

} else {
    logger.error("User has submitted pairing code, checking status...");
    var response = httpClient.send(url, requestOptions).get();
    if (response.status === 200) {
        try {
            var responseJson = JSON.parse(response.json());
        } catch (e) {
            logger.error("Failed to parse JSON: " + e);
        }
        if (responseJson.status === "CLAIMED") {
            logger.info("Device successfully paired.");
            action.goTo("true");
        }
    }
}
"

9caca129-45ef-4337-98a6-d47c90148c23.script:
"/**
 * Created by the Ping Identity Technology Alliance Partner (TAP) team
 *
 * For support, contact Ping Identity Support
 * or email: tap-global@pingidentity.com
 *
 * Version: 1.5
 */

var deviceAuthId = nodeState.get("deviceAuthId");
var accessToken = nodeState.get("pingAccessToken");
var envId = systemEnv.getProperty("esv.envid");

if (!deviceAuthId || !accessToken || !envId) {
    logger.error("Missing required state. envId/deviceAuthId/accessToken must be present.");
    nodeState.putShared("deviceAuthStatusError", "Missing envId, deviceAuthId, or accessToken");
    action.goTo("error");
} else {
    var requestUrl = "https://auth.pingone.com/" + envId + "/deviceAuthentications/" + deviceAuthId;

    var requestOptions = {
        method: "GET",
        headers: {
            "Content-Type": "application/json",
        },
        token: accessToken
    };

    try {
        var response = httpClient.send(requestUrl, requestOptions).get();

        if (!response) {
            logger.error("No response returned from device authentication API");
            nodeState.putShared("deviceAuthStatusError", "No response returned from API");
            action.goTo("error");
        } else if (!response.ok) {
            var errorBody = response.text();
            logger.error("Device authentication API call failed. HTTP status: " + response.status + ", body: " + errorBody);
            nodeState.putShared("deviceAuthHttpStatus", String(response.status));
            nodeState.putShared("deviceAuthStatusError", errorBody);
            action.goTo("error");
        } else {
            var body = response.json();
            var status = body && body.status ? String(body.status) : null;


            nodeState.putShared("deviceAuthApiResponse", JSON.stringify(body));
            nodeState.putShared("deviceAuthStatus", status);

            if (status === "PUSH_CONFIRMATION_REQUIRED") {
                action.goTo("polling");
            } else if (status === "COMPLETED") {
                action.goTo("completed");
            } else {
                logger.error("Unexpected device authentication status: " + status);
                nodeState.putShared("deviceAuthStatusError", "Unexpected status: " + status);
                action.goTo("error");
            }
        }
    } catch (e) {
        logger.error("Exception while calling device authentication API: " + e);
        nodeState.putShared("deviceAuthStatusError", String(e));
        action.goTo("error");
    }
}"

