 */

try {
  var environmentId = systemEnv.getProperty("esv.envid");
  var accessToken = nodeState.get("pingAccessToken");
  var userId = nodeState.get("pingOneUserId");

  var url =
    "https://api.pingone.com/v1/environments/" +
    environmentId +
    "/users/" +
    userId +
    "/devices";

  var requestOptions = {
    method: "GET",
    headers: {
      "Accept": "application/json"
    },
    token: accessToken
  };

  var response = httpClient.send(url, requestOptions).get();

  if (response.status !== 200) {
    logger.error("PingOne Devices API failed. Status: " + response.status);
    action.goTo("error");
  } else {
    var json = response.json();
    var count = json.count || 0;

    nodeState.putShared("devicesResponse", JSON.stringify(json));

    if (count === 0) {
      action.goTo("noDevices");
    } else if (count === 1) {
      var device = json._embedded.devices[0];

      nodeState.putShared("selectedDeviceId", device.id);
      nodeState.putShared("selectedDeviceNickname", device.nickname || device.id);

      action.goTo("singleDevice");
    } else {
      action.goTo("multipleDevices");
    }
  }
} catch (e) {
  logger.error("Exception calling PingOne Devices API: " + e);
  action.goTo("error");
}"

d69d93b9-dadf-4182-9627-cb1400ab8dd1.script:
"/**
 * Created by the Ping Identity Technology Alliance Partner (TAP) team
 *
 * For support, contact Ping Identity Support
 * or email: tap-global@pingidentity.com
 *
 * Version: 1.5
 */

try {
  var devicesJson = nodeState.get("devicesResponse");
  var devicesResponse = JSON.parse(devicesJson);

  var devices = devicesResponse._embedded.devices;

  var choices = [];
  var deviceIds = [];

  for (var i = 0; i < devices.length; i++) {
    var d = devices[i];

    var label = d.nickname ||
            (d.model && d.model.marketingName) ||
            d.id;

    if (d.os && d.os.type) {
      label += " - " + d.os.type;
    }

    choices.push(label);
    deviceIds.push(d.id);
  }

  if (callbacks.isEmpty()) {
    callbacksBuilder.choiceCallback(
      "Select the device you want to use",
      choices,
      0,
      false
    );
  } else {
    var selectedIndex = callbacks.getChoiceCallbacks().get(0)[0];

    var selectedDeviceId = deviceIds[selectedIndex];
    var selectedDeviceLabel = choices[selectedIndex];

    nodeState.putShared("selectedDeviceId", selectedDeviceId);
    nodeState.putShared("selectedDeviceLabel", selectedDeviceLabel);

    action.goTo("selected");
  }

} catch (e) {
  logger.error("Error rendering device choices: " + e);
  action.goTo("error");
}"

